class Solution:
    def maximumPoints(self, enemyEnergies: List[int], currentEnergy: int) -> int:
        m = min(enemyEnergies)
        if currentEnergy < m:
            return 0
        return (currentEnergy + sum(enemyEnergies) - m) // m

