class Solution {
    public long maximumPoints(int[] enemyEnergies, int currentEnergy) {
        long m = Long.MAX_VALUE, s = 0;
        for (int e : enemyEnergies) { m = Math.min(m, e); s += e; }
        if (currentEnergy < m) return 0;
        return (currentEnergy + s - m) / m;
    }
}

