class Solution:
    def maximumPoints(self, enemyEnergies: List[int], currentEnergy: int) -> int:
        e = sorted(enemyEnergies)
        i, j, pts = 0, len(e) - 1, 0
        while True:
            if currentEnergy >= e[i]:
                currentEnergy -= e[i]; pts += 1
            elif pts > 0 and j > i:
                currentEnergy += e[j]; j -= 1
            else:
                return pts

