class Solution {
public:
    long long maximumPoints(vector<int>& ee, int currentEnergy) {
        sort(ee.begin(), ee.end());
        int i = 0, j = ee.size() - 1; long long pts = 0;
        while (true) {
            if (currentEnergy >= ee[i]) { currentEnergy -= ee[i]; ++pts; }
            else if (pts > 0 && j > i) { currentEnergy += ee[j]; --j; }
            else return pts;
        }
    }
};

